  let seed = 1337;
  const rand = () => {
    seed = (seed * 1664525 + 1013904223) >>> 0;
    return seed / 4294967296;
  };
  const stars = Array.from({ length: Math.round(size * size / 900) }, () => ({
    x: rand() * size,
    y: rand() * size,
    r: 0.5 + rand() * (size / 300)
  }));

  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const nx = (x - c) / (size / 2);
      const ny = (y - c) / (size / 2);
      const dist = Math.sqrt(nx * nx + ny * ny);

      const top = [8, 19, 38];
      const bottom = [16, 35, 62];
      const t = (ny + 1) / 2;
      let r = top[0] + (bottom[0] - top[0]) * t;
      let g = top[1] + (bottom[1] - top[1]) * t;
      let b = top[2] + (bottom[2] - top[2]) * t;

      const glow = Math.exp(-dist * dist * 4.2);
      r += 30 * glow;
      g += 74 * glow;
      b += 110 * glow;

      const vertical = Math.abs(nx) * 0.2 + Math.abs(ny) < 0.74;
      const horizontal = Math.abs(ny) * 0.2 + Math.abs(nx) < 0.5;
      const star = vertical || horizontal;
      const starGlow = Math.exp(-(Math.abs(nx) * 2 + Math.abs(ny) * 2));
      if (star) {
        const mix = Math.min(1, 0.55 + starGlow * 0.6);
        r = r * (1 - mix) + 126 * mix;
        g = g * (1 - mix) + 231 * mix;
        b = b * (1 - mix) + 255 * mix;
      }

      const ring = Math.abs(dist - 0.57) < 0.018;
      if (ring) {
        r = r * 0.25 + 141 * 0.75;
        g = g * 0.25 + 123 * 0.75;
        b = b * 0.25 + 255 * 0.75;
      }

      const core = dist < 0.075;
      if (core) {
        r = 238; g = 250; b = 255;
      }

      for (const dot of stars) {
        const dx = x - dot.x;
        const dy = y - dot.y;
        if (dx * dx + dy * dy < dot.r * dot.r) {
          const fade = 0.45 + rand() * 0.4;
          r = r * (1 - fade) + 230 * fade;
          g = g * (1 - fade) + 245 * fade;
          b = b * (1 - fade) + 255 * fade;
        }
      }

      const i = (y * size + x) * 4;
      pixels[i] = Math.max(0, Math.min(255, Math.round(r)));
      pixels[i + 1] = Math.max(0, Math.min(255, Math.round(g)));
      pixels[i + 2] = Math.max(0, Math.min(255, Math.round(b)));
      pixels[i + 3] = 255;
    }
  }

  const raw = Buffer.alloc((size * 4 + 1) * size);
  for (let y = 0; y < size; y += 1) {
    raw[y * (size * 4 + 1)] = 0;
    pixels.copy(raw, y * (size * 4 + 1) + 1, y * size * 4, (y + 1) * size * 4);
  }

  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  ihdr[10] = 0;
  ihdr[11] = 0;
  ihdr[12] = 0;

  const png = Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk('IHDR', ihdr),
    chunk('IDAT', zlib.deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0))
  ]);
  fs.writeFileSync(file, png);
  return png.length;
}

for (const size of [192, 512]) {
  const file = path.join('icons', `icon-${size}.png`);
  const bytes = writePng(file, size);
  console.log(file, `${bytes} bytes`);
}
